SELECT     im.DEPT                                               AS \"DEPT NO\",     d.DEPT_NAME                                           AS \"DEPT NAME\",     im.CLASS                                              AS \"CLASS NO\",     im.SUBCLASS                                           AS \"SUBCLASS NO\",     im.ITEM                                               AS \"ITEM ID\",     im.ITEM_DESC                                          AS \"ITEM DESCRIPTION\",     im.STANDARD_UOM                                       AS \"UOM\",     il.LOC                                                AS \"LOCATION ID\",     il.LOC_TYPE                                           AS \"LOCATION TYPE\",     CASE il.LOC_TYPE WHEN 'S' THEN st.STORE_NAME WHEN 'W' THEN wh.WH_NAME END                                                           AS \"LOCATION NAME\",     il.STATUS                                             AS \"ITEM LOC STATUS\",     ils.UNIT_COST                                         AS \"CURRENT UNIT COST\",     ils.AV_COST                                           AS \"WEIGHTED AVG COST\",     il.UNIT_RETAIL                                        AS \"CURRENT RETAIL\",     il.SELLING_UNIT_RETAIL                                AS \"SELLING UNIT RETAIL\",     CASE WHEN il.SELLING_UNIT_RETAIL &gt; 0 AND ils.AV_COST &gt; 0          THEN ROUND((il.SELLING_UNIT_RETAIL - ils.AV_COST)/il.SELLING_UNIT_RETAIL*100,2)     END                                                   AS \"MARGIN PERCENT\",     ils.STOCK_ON_HAND                                     AS \"STOCK ON HAND\"  FROM  MFCS_RDS.RDS_WV_ITEM_LOC                il JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER             im   ON il.ITEM  = im.ITEM AND im.TRAN_LEVEL = im.ITEM_LEVEL JOIN  MFCS_RDS.RDS_WV_DEPS                    d    ON im.DEPT  = d.DEPT JOIN  MFCS_RDS.RDS_WV_CLASS                   c    ON im.DEPT  = c.DEPT AND im.CLASS = c.CLASS JOIN  MFCS_RDS.RDS_WV_SUBCLASS                sc   ON im.DEPT  = sc.DEPT AND im.CLASS = sc